-- Conciliacao BAIFER ITAU 08/2026 (gerada em 23/09/2026 na 179.199.149.12)
-- Busca empresa e banco pelo nome. Nao duplica se ja existir.
DO $chk$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM empresas WHERE nome = $q$BAIFER DISTRIBUIDORA$q$) THEN
    RAISE EXCEPTION 'Empresa % nao encontrada neste banco', $q$BAIFER DISTRIBUIDORA$q$;
  END IF;
  IF EXISTS (SELECT 1 FROM conciliacoes c JOIN empresas e ON e.id = c.empresa_id
             WHERE e.nome = $q$BAIFER DISTRIBUIDORA$q$ AND c.competencia = $q$2026-08$q$
               AND c.banco_nome = $q$ITAU BAIFER$q$ AND c.id <> $q$9325b5d5-ae64-4b7d-80ef-314c5e76c74a$q$) THEN
    RAISE NOTICE 'Atencao: ja existe outra conciliacao 2026-08 ITAU BAIFER nesta empresa';
  END IF;
END
$chk$;
